import re
import sys
from datetime import date

SWISS = re.compile(r"([0-9]{1,2})\.([0-9]{1,2})\.([0-9]{4})")
ISO = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")

def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def plausible(y, m, d):
    if m < 1 or m > 12:
        return False
    if d < 1:
        return False
    if m == 2:
        if d > 29:
            return False
        if d == 29 and not is_leap(y):
            return False
    elif m in [4, 6, 9, 11]:
        if d > 30:
            return False
    return True

def convert(text):
    m = SWISS.fullmatch(text)
    if m:
        d, mo, y = map(int, m.groups())
        if plausible(y, mo, d):
            return f"{y:04d}-{mo:02d}-{d:02d}"
        return "invalid"
    m = ISO.fullmatch(text)
    if m:
        y, mo, d = map(int, m.groups())
        if plausible(y, mo, d):
            return f"{d:02d}.{mo:02d}.{y:04d}"
        return "invalid"
    return "invalid"

def main():
    for line in sys.stdin:
        text = line.strip()
        if text:
            print(convert(text))

if __name__ == "__main__":
    main()
